-- generated by tools/gencatalog, do not edit by hand
CREATE EXTENSION IF NOT EXISTS btree_gist;

CREATE TABLE salaries (
    id BIGINT PRIMARY KEY GENERATED ALWAYS AS IDENTITY,
    employee_id BIGINT REFERENCES employees(id) NOT NULL,
    amount NUMERIC(14,2) NOT NULL,
    currency_id BIGINT REFERENCES currencies(id) NOT NULL,
    start_date DATE NOT NULL,
    end_date DATE,
    is_deleted BOOLEAN NOT NULL DEFAULT FALSE,
    CONSTRAINT chk_salaries_amount CHECK (amount > 0),
    CONSTRAINT chk_salaries_period CHECK (end_date IS NULL OR end_date >= start_date),
    CONSTRAINT excl_salaries_employee_period EXCLUDE USING gist (employee_id WITH =, daterange(start_date, end_date, '[]') WITH &&) WHERE (NOT is_deleted)
);

CREATE TABLE salary_revisions (
    id              BIGINT       PRIMARY KEY GENERATED ALWAYS AS IDENTITY,
    salary_id BIGINT       NOT NULL REFERENCES salaries(id) ON DELETE CASCADE,
    revision_number INTEGER      NOT NULL CHECK (revision_number >= 1),
    change          JSONB        NOT NULL,
    changed_by      UUID         NOT NULL,
    changed_at      TIMESTAMPTZ  NOT NULL DEFAULT now(),

    CONSTRAINT uq_salary_revisions_revision
        UNIQUE (salary_id, revision_number)
);

CREATE INDEX idx_salaries_employee_id
    ON salaries (employee_id);

CREATE INDEX idx_salaries_currency_id
    ON salaries (currency_id);

CREATE INDEX idx_salaries_active
    ON salaries (id)
    WHERE is_deleted = FALSE;

CREATE INDEX idx_salary_revisions_salary_id
    ON salary_revisions (salary_id);

CREATE INDEX idx_salary_revisions_covering_agg
    ON salary_revisions (salary_id, revision_number DESC)
    INCLUDE (changed_at, changed_by, change);

CREATE INDEX idx_salary_revisions_changed_at
    ON salary_revisions (changed_at);

CREATE OR REPLACE VIEW v_expanded_salary AS
SELECT
    t.id,
    t.employee_id,
    t.amount,
    t.currency_id,
    t.start_date,
    t.end_date,
    t.is_deleted,
    agg.revision,
    agg.last_changer,
    agg.created_at,
    agg.updated_at,
    agg.deleted_at
FROM salaries t
LEFT JOIN (
    SELECT
        salary_id,
        MAX(revision_number) AS revision,
        MAX(changed_at) AS updated_at,
        (ARRAY_AGG(changed_by ORDER BY revision_number DESC))[1] AS last_changer,
        MIN(changed_at) FILTER (WHERE revision_number = 1) AS created_at,
        MAX(changed_at) FILTER (
            WHERE change @> '[{"path": "/is_deleted", "value": true}]'::jsonb
        ) AS deleted_at
    FROM salary_revisions
    GROUP BY salary_id
) agg ON agg.salary_id = t.id;

COMMENT ON TABLE salaries IS
    'Monthly salaries of employees with the period they are in effect. Periods of one employee do not overlap. Readable by the HR roles only. Stores the current state of each record.';

COMMENT ON TABLE salary_revisions IS
    'Immutable audit log of changes applied to salaries. Read-only from the application perspective.';

COMMENT ON VIEW v_expanded_salary IS
    'Read-only view that enriches each salary with its latest revision number, '
    'last changer UUID, and lifecycle timestamps derived from the revision log.';
